import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { nextInvoiceNumber } from '../src/numbering.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2026-10-07');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 5);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);
});

test('createInvoice with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
});

test('createInvoice reports CUSTOMER_NOT_FOUND', () => {
  const result = createInvoice({
    customerId: 'NOPE',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for wrong format', () => {
  const testCases = [
    '10-07-2026',
    '2026/10/07',
    '2026-1-7',
    '2026-10-7',
    'not-a-date',
    '2026-13-01',
    '2026-12-32',
  ];
  for (const dateStr of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Should reject ${dateStr}`);
    assert.equal(result.error, 'DATE_INVALID');
  }
});

test('createInvoice accepts valid dates', () => {
  const validDates = [
    '2026-01-01',
    '2026-12-31',
    '2024-02-29', // leap year
    '2025-02-28', // non-leap year
  ];
  for (const dateStr of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `Should accept ${dateStr}`);
  }
});

test('createInvoice reports DATE_INVALID for invalid dates', () => {
  const invalidDates = [
    '2025-02-29', // non-leap year
    '2026-04-31', // April has 30 days
  ];
  for (const dateStr of invalidDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Should reject ${dateStr}`);
    assert.equal(result.error, 'DATE_INVALID');
  }
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports NO_LINES for missing lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer qty', () => {
  const testCases = [1.5, '5', NaN, Infinity];
  for (const qty of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Should reject qty ${qty}`);
    assert.equal(result.error, 'QTY_INVALID');
  }
});

test('createInvoice reports QTY_INVALID for zero or negative qty', () => {
  const testCases = [0, -1, -100];
  for (const qty of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Should reject qty ${qty}`);
    assert.equal(result.error, 'QTY_INVALID');
  }
});

test('createInvoice reports UNKNOWN_SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const inputLines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalLine = { ...inputLines[0] };
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: inputLines,
  });
  assert.deepEqual(inputLines[0], originalLine);
});

test('createInvoice stops at first error', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'NOPE', qty: 0 }, // Both SKU unknown and qty invalid
    ],
  });
  // Should report QTY_INVALID since it checks qty before SKU in the second line
  assert.equal(result.error, 'QTY_INVALID');
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1000 }), 1000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 50 }), 500);
  assert.equal(lineTotal({ qty: 100, unitPrice: 0 }), 0);
});

test('lineTotal returns cents (integers)', () => {
  const total = lineTotal({ qty: 3, unitPrice: 1000 });
  assert.ok(Number.isInteger(total));
  assert.equal(total, 3000);
});

test('invoiceTotals sums line totals for single line', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 8500 },
      { qty: 2, unitPrice: 9500 },
      { qty: 1, unitPrice: 6000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 3 * 8500 + 2 * 9500 + 1 * 6000;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals with enriched invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 2 * 8500 + 3 * 9500; // 45500
  const line1Vat = Math.round(17000 * 21 / 100); // 3570
  const line2Vat = Math.round(28500 * 21 / 100); // 5985
  const totalVat = line1Vat + line2Vat; // 9555

  assert.equal(totals.subtotal, 45500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 9555);
  assert.equal(totals.total, 45500 + 9555);
});

test('invoiceTotals with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns integers', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 2, unitPrice: 1000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(Number.isInteger(totals.subtotal));
  assert.ok(Number.isInteger(totals.total));
});

test('invoiceTotals does not mutate input', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 2, unitPrice: 9500 },
    ],
  };
  const originalLines = JSON.stringify(invoice.lines);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice.lines), originalLines);
});

test('addLine adds a new line to a draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(addResult.ok, true);
  const newInvoice = addResult.value;
  assert.equal(newInvoice.lines.length, 2);
  assert.equal(newInvoice.lines[1].sku, 'DEV-HOUR');
  assert.equal(newInvoice.lines[1].qty, 3);
  assert.equal(newInvoice.lines[1].name, 'Development (hour)');
});

test('addLine updates qty for existing SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(addResult.ok, true);
  const newInvoice = addResult.value;
  assert.equal(newInvoice.lines.length, 1);
  assert.equal(newInvoice.lines[0].qty, 5);
});

test('addLine validates qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = result.value;

  const testCases = [0, -1, 1.5, 'string'];
  for (const qty of testCases) {
    const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty });
    assert.equal(addResult.ok, false, `Should reject qty ${qty}`);
    assert.equal(addResult.error, 'QTY_INVALID');
  }
});

test('addLine validates SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'UNKNOWN', qty: 1 });
  assert.equal(addResult.ok, false);
  assert.equal(addResult.error, 'UNKNOWN_SKU');
});

test('addLine refuses to modify non-draft invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = result.value;
  const nonDraftInvoice = { ...invoice, status: 'sent' };

  const addResult = addLine(nonDraftInvoice, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(addResult.ok, false);
  assert.equal(addResult.error, 'NOT_DRAFT');
});

test('addLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const invoice = result.value;
  const originalLines = JSON.stringify(invoice.lines);

  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(JSON.stringify(invoice.lines), originalLines);
});

test('removeLine removes a line from a draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const invoice = result.value;

  const removeResult = removeLine(invoice, 'DES-HOUR');
  assert.equal(removeResult.ok, true);
  const newInvoice = removeResult.value;
  assert.equal(newInvoice.lines.length, 1);
  assert.equal(newInvoice.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND for unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = result.value;

  const removeResult = removeLine(invoice, 'UNKNOWN');
  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'LINE_NOT_FOUND');
});

test('removeLine reports NO_LINES if removing last line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = result.value;

  const removeResult = removeLine(invoice, 'DES-HOUR');
  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'NO_LINES');
});

test('removeLine refuses to modify non-draft invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  const invoice = result.value;
  const nonDraftInvoice = { ...invoice, status: 'sent' };

  const removeResult = removeLine(nonDraftInvoice, 'DES-HOUR');
  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'NOT_DRAFT');
});

test('removeLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const invoice = result.value;
  const originalLines = JSON.stringify(invoice.lines);

  removeLine(invoice, 'DES-HOUR');
  assert.equal(JSON.stringify(invoice.lines), originalLines);
});

test('nextInvoiceNumber generates first invoice for a year', () => {
  const number = nextInvoiceNumber([], '2026-10-07');
  assert.equal(number, 'INV-2026-0001');
});

test('nextInvoiceNumber increments counter within same year', () => {
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const number = nextInvoiceNumber(existing, '2026-10-07');
  assert.equal(number, 'INV-2026-0003');
});

test('nextInvoiceNumber resets counter for new year', () => {
  const existing = ['INV-2025-0001', 'INV-2025-0002', 'INV-2026-0001'];
  const number = nextInvoiceNumber(existing, '2027-01-01');
  assert.equal(number, 'INV-2027-0001');
});

test('nextInvoiceNumber handles out-of-order existing numbers', () => {
  const existing = ['INV-2026-0003', 'INV-2026-0001', 'INV-2026-0002'];
  const number = nextInvoiceNumber(existing, '2026-10-07');
  assert.equal(number, 'INV-2026-0004');
});

test('nextInvoiceNumber finds max counter across multiple years', () => {
  const existing = [
    'INV-2025-0099',
    'INV-2026-0001',
    'INV-2026-0010',
    'INV-2026-0005',
  ];
  const number = nextInvoiceNumber(existing, '2026-06-15');
  assert.equal(number, 'INV-2026-0011');
});

test('nextInvoiceNumber zero-pads counter to 4 digits', () => {
  const existing = Array.from({ length: 9 }, (_, i) => `INV-2026-000${i + 1}`);
  const number = nextInvoiceNumber(existing, '2026-10-07');
  assert.equal(number, 'INV-2026-0010');
});

test('issueInvoice converts draft invoice to issued with number', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const invoice = result.value;

  const issueResult = issueInvoice(invoice, []);
  assert.equal(issueResult.ok, true);
  const issuedInvoice = issueResult.value;
  assert.equal(issuedInvoice.status, 'issued');
  assert.equal(issuedInvoice.number, 'INV-2026-0001');
  assert.equal(issuedInvoice.customerId, 'C-001');
  assert.equal(issuedInvoice.issueDate, '2026-10-07');
  assert.equal(issuedInvoice.lines.length, 1);
});

test('issueInvoice uses correct next number with existing invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = result.value;
  const existing = ['INV-2026-0001', 'INV-2026-0002'];

  const issueResult = issueInvoice(invoice, existing);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2026-0003');
});

test('issueInvoice rejects non-draft invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = result.value;
  const issuedInvoice = { ...invoice, status: 'issued' };

  const issueResult = issueInvoice(issuedInvoice, []);
  assert.equal(issueResult.ok, false);
  assert.equal(issueResult.error, 'NOT_DRAFT');
});

test('issueInvoice does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const invoice = result.value;
  const originalStatus = invoice.status;
  const originalLines = JSON.stringify(invoice.lines);

  issueInvoice(invoice, []);
  assert.equal(invoice.status, originalStatus);
  assert.equal(JSON.stringify(invoice.lines), originalLines);
  assert.equal(invoice.number, undefined);
});

test('issueInvoice preserves all invoice data', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  const invoice = result.value;

  const issueResult = issueInvoice(invoice, ['INV-2025-0001']);
  assert.equal(issueResult.ok, true);
  const issued = issueResult.value;
  assert.equal(issued.customerId, 'C-002');
  assert.equal(issued.issueDate, '2025-01-15');
  assert.equal(issued.lines.length, 2);
  assert.equal(issued.lines[0].sku, 'DES-HOUR');
  assert.equal(issued.lines[0].qty, 3);
  assert.equal(issued.lines[1].sku, 'DEV-HOUR');
  assert.equal(issued.lines[1].qty, 2);
  assert.equal(issued.number, 'INV-2025-0002');
});

test('createInvoice accepts valid discountPercent values', () => {
  const validDiscounts = [0, 50, 100, 12.5, 0.01, 99.99];
  for (const discount of validDiscounts) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: discount }],
    });
    assert.equal(result.ok, true, `Should accept discountPercent ${discount}`);
    assert.equal(result.value.lines[0].discountPercent, discount);
  }
});

test('createInvoice reports DISCOUNT_INVALID for invalid discountPercent', () => {
  const invalidDiscounts = [-1, 101, 'invalid', NaN, Infinity, -Infinity, null];
  for (const discount of invalidDiscounts) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: discount }],
    });
    assert.equal(result.ok, false, `Should reject discountPercent ${discount}`);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  }
});

test('createInvoice without discountPercent applies tier discount for gold', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5); // gold tier discount
});

test('createInvoice without discountPercent omits it for standard tier', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined); // no tier discount
});

test('addLine accepts valid discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const invoice = result.value;

